tool.command:
@PREPARE_BAMS@
mkdir results &&
scBulkCoverage
    @BAM_ARGS@
    --groupInfo '$groupInfo'
    --outFilePrefix results/coverage
    --outFileFormat '$outFileFormat'
    --normalizeUsing '$normalization.normalizeUsing'
    #if str($normalization.ignoreForNormalization).strip():
        --ignoreForNormalization
        #for $chrom in str($normalization.ignoreForNormalization).split(',')
            #if $chrom.strip()
                '${chrom.strip()}'
            #end if
        #end for
    #end if
    --scaleFactor $normalization.scaleFactor
    @CELL_TAG_CMD@
    --binSize $binSize
    @REGION_CMD@
    @EXCLUSION_CMD@
    @READ_FILTERS_CMD@
    @FRAGMENT_LENGTH_CMD@
    @SEQUENCE_FILTERS_CMD@
    @RNA_STRAND_CMD@
    @READ_PROCESSING_CMD@
    $processing.MNase
    #if str($processing.Offset).strip():
        --Offset $processing.Offset
    #end if
    @THREADS@
